+package main
+
+import (
+	"context"
+	"encoding/json"
+	"errors"
+	"flag"
+	"fmt"
+	"io"
+	"net/http"
+	"os"
+	"sort"
+	"strings"
+	"time"
+)
+
+// feedbackStats is what people did with px1's inline comments: the only
+// precision signal that comes from real use instead of a seeded benchmark.
+type feedbackStats struct {
+	Repo       string            `json:"repo"`
+	Since      string            `json:"since"`
+	Comments   int               `json:"comments"`
+	ThumbsUp   int               `json:"thumbs_up"`
+	ThumbsDown int               `json:"thumbs_down"`
+	Replied    int               `json:"replied"`
+	Engaged    int               `json:"engaged"` // reacted to or replied to
+	Findings   []feedbackFinding `json:"findings"`
+}
+
+type feedbackFinding struct {
+	PullRequest string `json:"pull_request"`
+	Path        string `json:"path"`
+	Line        int    `json:"line"`
+	Title       string `json:"title"`
+	ThumbsUp    int    `json:"thumbs_up"`
+	ThumbsDown  int    `json:"thumbs_down"`
+	Replies     int    `json:"replies"`
+}
+
+// Acceptance is thumbs-up out of all thumbs. It is undefined (ok=false) until
+// someone has reacted: silence is not agreement.
+func (s feedbackStats) Acceptance() (float64, bool) {
+	if s.ThumbsUp+s.ThumbsDown == 0 {
+		return 0, false
+	}
+	return float64(s.ThumbsUp) / float64(s.ThumbsUp+s.ThumbsDown), true
+}
+
+func runFeedbackCollect(args []string, stdout io.Writer) error {
+	fs := flag.NewFlagSet("feedback-collect", flag.ContinueOnError)
+	fs.SetOutput(os.Stderr)
+	repo := fs.String("repo", os.Getenv("GITHUB_REPOSITORY"), "owner/name (default: $GITHUB_REPOSITORY)")
+	days := fs.Int("days", 30, "only comments from the last N days")
+	apiURL := fs.String("api-url", envOr("GITHUB_API_URL", "https://api.github.com"), "GitHub API base URL")
+	out := fs.String("out", "", "optional file for the JSON result")
+	if err := fs.Parse(args); err != nil {
+		return err
+	}
+	if !validRepoSlug(*repo) || *days < 1 || *days > 365 {
+		return errors.New("feedback-collect requires --repo owner/name and --days between 1 and 365")
+	}
+	token := os.Getenv("GITHUB_TOKEN")
+	if token == "" {
+		return errors.New("GITHUB_TOKEN is required (for a private repository try GITHUB_TOKEN=$(gh auth token))")
+	}
+	gh := githubClient{base: strings.TrimRight(*apiURL, "/"), token: token, http: &http.Client{Timeout: 30 * time.Second}}
+	since := time.Now().UTC().AddDate(0, 0, -*days)
+	stats, err := collectFeedback(context.Background(), gh, *repo, since)
+	if err != nil {
+		return err
+	}
+	if *out != "" {
+		data, _ := json.MarshalIndent(stats, "", "  ")
+		if err := os.WriteFile(*out, append(data, '\n'), 0o600); err != nil {
+			return err
+		}
+	}
+	_, err = io.WriteString(stdout, stats.Markdown())
+	return err
+}
+
+type reviewCommentAPI struct {
+	ID          int64     `json:"id"`
+	InReplyTo   int64     `json:"in_reply_to_id"`
+	Body        string    `json:"body"`
+	Path        string    `json:"path"`
+	Line        int       `json:"line"`
+	PullRequest string    `json:"pull_request_url"`
+	CreatedAt   time.Time `json:"created_at"`
+	User        struct {
+		Type string `json:"type"`
+	} `json:"user"`
+	Reactions struct {
+		Up   int `json:"+1"`
+		Down int `json:"-1"`
+	} `json:"reactions"`
+}
+
+func collectFeedback(ctx context.Context, gh githubClient, repo string, since time.Time) (feedbackStats, error) {
+	stats := feedbackStats{Repo: repo, Since: since.Format("2006-01-02")}
+	var all []reviewCommentAPI
+	for page := 1; page <= maxFilePages; page++ {
+		var comments []reviewCommentAPI
+		path := fmt.Sprintf("%s/pulls/comments?per_page=100&sort=created&direction=desc&since=%s&page=%d", repoPath(repo), since.Format(time.RFC3339), page)
+		if err := gh.do(ctx, http.MethodGet, path, nil, &comments); err != nil {
+			return stats, err
+		}
+		all = append(all, comments...)
+		if len(comments) < 100 {
+			break
+		}
+	}
+	replies := map[int64]int{}
+	for _, c := range all {
+		if c.InReplyTo != 0 && c.User.Type != "Bot" {
+			replies[c.InReplyTo]++
+		}
+	}
+	for _, c := range all {
+		if c.InReplyTo != 0 || c.CreatedAt.Before(since) || !strings.Contains(c.Body, "<!-- px1-finding:") {
+			continue
+		}
+		f := feedbackFinding{PullRequest: c.PullRequest, Path: c.Path, Line: c.Line, Title: findingTitle(c.Body),
+			ThumbsUp: c.Reactions.Up, ThumbsDown: c.Reactions.Down, Replies: replies[c.ID]}
+		stats.Comments++
+		stats.ThumbsUp += f.ThumbsUp
+		stats.ThumbsDown += f.ThumbsDown
+		if f.Replies > 0 {
+			stats.Replied++
+		}
+		if f.ThumbsUp+f.ThumbsDown+f.Replies > 0 {
+			stats.Engaged++
+		}
+		stats.Findings = append(stats.Findings, f)
+	}
+	sort.SliceStable(stats.Findings, func(i, j int) bool {
+		return stats.Findings[i].ThumbsDown-stats.Findings[i].ThumbsUp > stats.Findings[j].ThumbsDown-stats.Findings[j].ThumbsUp
+	})
+	return stats, nil
+}
+
+// findingTitle pulls the bold "**P2: title**" line out of an inline comment.
+func findingTitle(body string) string {
+	for _, line := range strings.Split(body, "\n") {
+		if strings.HasPrefix(line, "**") && strings.HasSuffix(line, "**") {
+			return strings.Trim(line, "*")
+		}
+	}
+	return ""
+}
+
+func (s feedbackStats) Markdown() string {
+	var b strings.Builder
+	fmt.Fprintf(&b, "# px1 feedback on %s since %s\n\n", s.Repo, s.Since)
+	if s.Comments == 0 {
+		b.WriteString("No px1 inline comments in this period.\n")
+		return b.String()
+	}
+	fmt.Fprintf(&b, "- %d inline comments; %d reacted to or replied to (%.0f%% engaged)\n", s.Comments, s.Engaged, 100*float64(s.Engaged)/float64(s.Comments))
+	fmt.Fprintf(&b, "- 👍 %d, 👎 %d, replies on %d comments\n", s.ThumbsUp, s.ThumbsDown, s.Replied)
+	if a, ok := s.Acceptance(); ok {
+		fmt.Fprintf(&b, "- **Acceptance %.0f%%** of reactions were 👍 (from %d reactions; read it as a rough signal, people react to few comments)\n", a*100, s.ThumbsUp+s.ThumbsDown)
+	} else {
+		b.WriteString("- **Acceptance unknown:** nobody has reacted yet. Silence is not agreement.\n")
+	}
+	b.WriteString("\n| Finding | 👍 | 👎 | Replies |\n| --- | --- | --- | --- |\n")
+	for _, f := range s.Findings {
+		title := f.Title
+		if title == "" {
+			title = f.Path
+		}
+		fmt.Fprintf(&b, "| %s (`%s:%d`) | %d | %d | %d |\n", title, f.Path, f.Line, f.ThumbsUp, f.ThumbsDown, f.Replies)
+	}
+	return b.String()
+}

diff --git a/feedback_collect_test.go b/feedback_collect_test.go
new file mode 100644
index 0000000..18e988c
--- /dev/null
+++ b/feedback_collect_test.go
@@ -0,0 +1,113 @@
+package main
+
+import (
+	"bytes"
+	"encoding/json"
+	"net/http"
+	"net/http/httptest"
+	"os"
+	"path/filepath"
+	"strings"
+	"testing"
+	"time"
+)
+
+func px1Comment(id int64, title string, up, down int, created time.Time) map[string]any {
+	return map[string]any{"id": id, "body": "<!-- px1-finding:abcdef123456 -->\n**P2: " + title + "**\n\nwhy", "path": "src/a.ts", "line": 10,
+		"pull_request_url": "https://api.github.com/repos/o/r/pulls/7", "created_at": created.Format(time.RFC3339),
+		"user": map[string]any{"type": "Bot"}, "reactions": map[string]any{"+1": up, "-1": down}}
+}
+
+func fakeCommentsServer(t *testing.T, comments []map[string]any) *httptest.Server {
+	t.Helper()
+	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		if r.Header.Get("Authorization") != "Bearer tok" || !strings.HasSuffix(r.URL.Path, "/repos/o/r/pulls/comments") {
+			http.Error(w, "no", http.StatusUnauthorized)
+			return
+		}
+		if r.URL.Query().Get("since") == "" {
+			http.Error(w, "since is required", http.StatusBadRequest)
+			return
+		}
+		json.NewEncoder(w).Encode(comments)
+	}))
+	t.Cleanup(server.Close)
+	return server
+}
+
+func TestFeedbackCollectCountsReactionsAndRepliesOnPx1CommentsOnly(t *testing.T) {
+	now := time.Now().UTC()
+	human := map[string]any{"id": int64(99), "body": "I disagree", "created_at": now.Format(time.RFC3339), "user": map[string]any{"type": "User"}, "in_reply_to_id": int64(1), "reactions": map[string]any{"+1": 5, "-1": 0}}
+	botReply := map[string]any{"id": int64(98), "body": "thanks", "created_at": now.Format(time.RFC3339), "user": map[string]any{"type": "Bot"}, "in_reply_to_id": int64(1)}
+	someoneElses := map[string]any{"id": int64(50), "body": "nit: rename this", "path": "x.ts", "created_at": now.Format(time.RFC3339), "user": map[string]any{"type": "User"}, "reactions": map[string]any{"+1": 9, "-1": 0}}
+	old := px1Comment(60, "Too old", 3, 0, now.AddDate(0, 0, -90))
+	server := fakeCommentsServer(t, []map[string]any{
+		px1Comment(1, "Boundary off by one", 2, 1, now), human, botReply, someoneElses, old,
+		px1Comment(2, "Never reacted", 0, 0, now),
+	})
+	t.Setenv("GITHUB_TOKEN", "tok")
+	out := filepath.Join(t.TempDir(), "fb.json")
+	var stdout bytes.Buffer
+	if err := runFeedbackCollect([]string{"--repo", "o/r", "--days", "30", "--api-url", server.URL, "--out", out}, &stdout); err != nil {
+		t.Fatal(err)
+	}
+	data, _ := os.ReadFile(out)
+	var stats feedbackStats
+	if err := json.Unmarshal(data, &stats); err != nil {
+		t.Fatal(err)
+	}
+	if stats.Comments != 2 || stats.ThumbsUp != 2 || stats.ThumbsDown != 1 || stats.Replied != 1 || stats.Engaged != 1 {
+		t.Fatalf("stats=%+v (a human reply and another person's comment must not count as px1's)", stats)
+	}
+	if a, ok := stats.Acceptance(); !ok || a < 0.66 || a > 0.67 {
+		t.Fatalf("acceptance=%v ok=%v", a, ok)
+	}
+	md := stdout.String()
+	for _, want := range []string{"2 inline comments", "Acceptance 67%", "Boundary off by one", "Never reacted"} {
+		if !strings.Contains(md, want) {
+			t.Fatalf("markdown lacks %q:\n%s", want, md)
+		}
+	}
+	if strings.Contains(md, "Too old") || strings.Contains(md, "rename this") {
+		t.Fatalf("out-of-period or non-px1 comments leaked in:\n%s", md)
+	}
+	info, _ := os.Stat(out)
+	if info.Mode().Perm() != 0o600 {
+		t.Fatalf("output is %v, want owner-only", info.Mode().Perm())
+	}
+}
+
+func TestFeedbackSilenceIsNotAgreement(t *testing.T) {
+	now := time.Now().UTC()
+	server := fakeCommentsServer(t, []map[string]any{px1Comment(1, "Quiet finding", 0, 0, now)})
+	t.Setenv("GITHUB_TOKEN", "tok")
+	var stdout bytes.Buffer
+	if err := runFeedbackCollect([]string{"--repo", "o/r", "--api-url", server.URL}, &stdout); err != nil {
+		t.Fatal(err)
+	}
+	if !strings.Contains(stdout.String(), "Acceptance unknown") || strings.Contains(stdout.String(), "Acceptance 0%") {
+		t.Fatalf("no reactions must read as unknown, not 0%% or 100%%:\n%s", stdout.String())
+	}
+}
+
+func TestFeedbackCollectEmptyAndInvalidInput(t *testing.T) {
+	server := fakeCommentsServer(t, nil)
+	t.Setenv("GITHUB_TOKEN", "tok")
+	var stdout bytes.Buffer
+	if err := runFeedbackCollect([]string{"--repo", "o/r", "--api-url", server.URL}, &stdout); err != nil || !strings.Contains(stdout.String(), "No px1 inline comments") {
+		t.Fatalf("err=%v out=%s", err, stdout.String())
+	}
+	for name, args := range map[string][]string{"bad repo": {"--repo", "nope"}, "zero days": {"--repo", "o/r", "--days", "0"}} {
+		if err := runFeedbackCollect(args, &bytes.Buffer{}); err == nil {
+			t.Errorf("%s accepted", name)
+		}
+	}
+	t.Setenv("GITHUB_TOKEN", "")
+	if err := runFeedbackCollect([]string{"--repo", "o/r", "--api-url", server.URL}, &bytes.Buffer{}); err == nil || !strings.Contains(err.Error(), "GITHUB_TOKEN") {
+		t.Fatalf("missing token: %v", err)
+	}
+	t.Setenv("GITHUB_TOKEN", "wrong-secret-token")
+	if err := runFeedbackCollect([]string{"--repo", "o/r", "--api-url", server.URL}, &bytes.Buffer{}); err == nil || strings.Contains(err.Error(), "wrong-secret-token") {
+		t.Fatalf("a rejected token must not be echoed: %v", err)
+	}
+}

